// node --test guardian/scamrules.test.cjs
// The rules actually served at /guardian/scamrules.js, checked against messages written to the Canadian
// Anti-Fraud Centre's published scam patterns and against ordinary messages (guardian/scam-corpus-ca.json).
// scamrules.js is generated by the Watchpost repo (scripts/build_scamrules_js.py); its tests prove the
// app and this file give the identical answer for every message.
const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const vm = require('node:vm');

const src = fs.readFileSync(path.join(__dirname, 'scamrules.js'), 'utf8');
const box = { window: {} };
vm.runInNewContext(src, box);
const R = box.window.ScamRules;
const C = JSON.parse(fs.readFileSync(path.join(__dirname, 'scam-corpus-ca.json'), 'utf8'));
const miss = new Set(C.known_misses.map((m) => m.id));

test('Canadian scam patterns get a warning (Moderate or higher)', () => {
  const missed = C.scam.filter((c) => !miss.has(c.id) && R.score(c.text).lvl < 2).map((c) => c.id);
  assert.deepEqual(missed, []);
});

test('ordinary messages are not flagged', () => {
  const flagged = C.legit.filter((c) => R.score(c.text).lvl >= 2).map((c) => c.id);
  assert.deepEqual(flagged, []);
});

test('each result names a next step, and a grandparent scam is not given romance advice', () => {
  const v = R.score("Grandma it's me, I'm in jail. The lawyer says bail is $5,000 in cash today. Don't tell mom.");
  assert.ok(v.lvl >= 3);
  assert.match(v.advice, /bail is never paid in cash/);
  assert.doesNotMatch(v.advice, /video call|reverse-image/);
});

test('French messages get a French answer', () => {
  const v = R.score("Maman c'est moi, j'ai un nouveau numero, j'ai brise mon telephone. Envoie-moi 700 $ par virement Interac maintenant.");
  assert.equal(v.lang, 'fr');
  assert.ok(v.lvl >= 3);
});

test('the rules file has no network code: the message is checked on the phone only', () => {
  for (const w of ['fetch(', 'XMLHttpRequest', 'sendBeacon', 'WebSocket', 'localStorage', 'document.cookie']) assert.ok(!src.includes(w), w);
});

test('the page loads the rules before using them and no longer carries its own copy', () => {
  const html = fs.readFileSync(path.join(__dirname, 'index.html'), 'utf8');
  assert.ok(!/const RULES=\[/.test(html), 'old inline rules removed');
  assert.ok(html.indexOf('/guardian/scamrules.js') > 0 && html.indexOf('/guardian/scamrules.js') < html.indexOf('ScamRules.score'));
  assert.match(fs.readFileSync(path.join(__dirname, 'sw.js'), 'utf8'), /\/guardian\/scamrules\.js/);
});
